import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Scope-Bound Arrow Environments","description":"","frontmatter":{"title":"Scope-Bound Arrow Environments","type":"adr","date":"2026-10-22T00:00:00.000Z","status":"landed","status_note":"Landed — dep bindings are arrows carrying their env; all three engines pass the plan gates."},"headers":[],"relativePath":"handl/project/adrs/0155-scope-bound-arrow-environments.md","filePath":"vendored/handl/project/adrs/0155-scope-bound-arrow-environments.md"}`),a={name:`handl/project/adrs/0155-scope-bound-arrow-environments.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0155-scope-bound-arrow-environments" tabindex="-1">ADR-0155: Scope-Bound Arrow Environments <a class="header-anchor" href="#adr-0155-scope-bound-arrow-environments" aria-label="Permalink to “ADR-0155: Scope-Bound Arrow Environments”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ol><li><strong>A dependency binding is a callable value</strong> — one payload kind, <strong>arrows</strong>: <code>.hnl</code>-authored deps and wrapped native deps. No second callable kind (ADR-0106).</li><li><strong>Name resolution does not change per engine.</strong> <code>proj_env</code>&#39;s scope-first lookup with string fallback stays; what changes is the environment record a arrow carries.</li><li><strong><code>ModuleEnv</code> (ADR-0156) becomes the builder</strong> of the lexical environment record; its shape is unchanged.</li><li><strong>Bootstrap is unchanged</strong>: <code>HandlLoader::new</code> builds the loader raw over <code>char</code> + <code>str-handl</code> and runs it on bytecode.</li><li><strong>Caching keys on <code>(module_id, env_id)</code></strong>: minted arrows capture the env, so <code>MODULE_VALUE_CACHE</code> can no longer key on <code>module_id</code> alone.</li><li><strong>Staged plan</strong>: <code>callv</code> node + wrap helpers → engine switch → cache keys, each gated by tree-walk and bytecode tests.</li><li><strong>Rejected: <code>TaggedValue::NativeFn(Rc&lt;NativeFnHandle&gt;)</code></strong> — a second callable kind at the value layer contradicts the pure arrow calculus (ADR-0106).</li></ol><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>Dependency functions were wrapped in engine-specific closures, so a scope-bound arrow could not capture the environment it was defined in and each engine resolved names its own way. Making the binding an arrow with its env record gives one resolution rule and serializable exports.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li><strong>A <code>NativeFn</code> value kind</strong> — the arrow is the only function former.</li><li><strong>Per-engine name resolution</strong> — resolution is shared; env records differ.</li><li><strong>Copy the environment per engine</strong> — the record is a value, carried by the arrow.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>Environment records become values; cache keys include <code>env_id</code>.</li><li>All engines share one resolution path and one wrap helper.</li><li>A native dep is wrapped once into an arrow, not once per engine.</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li><code>kernel/</code> — <code>proj_env</code>, <code>ModuleEnv</code>.</li><li><code>handl-runtime/</code> — <code>MODULE_VALUE_CACHE</code> keying.</li><li>Tree-walk and bytecode tests from the staged plan.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>+The callable-value shapes, resolution, interop, caching and the staged plan: +<a href="./../design/0155-scope-bound-arrow-environments.html"><code>design/0155-scope-bound-arrow-environments.md</code></a>.</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};